values
  ('7ce5f15c-7a05-40fd-a429-11daed020d24', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Microbial world and methods', 'This module establishes microbial world and methods as the course''s first working framework. It supplies the language and representations needed before the path advances to cell structure.', 0),
  ('5b508ae1-46a0-4494-af1f-2ec62e99b1bc', 'fde06c08-43a0-43a0-8201-1588c39f452a', '7ce5f15c-7a05-40fd-a429-11daed020d24', 'subtopic'::public.curated_course_node_type, 'Microscopy', 'Microscopy connects microbial world and methods to observable evidence and defines what a valid measurement or interpretation must support. It appears before cultivation because that next topic assumes this starting point.', 0),
  ('31bd758d-5c6f-4c5d-b38c-a0b535f80c78', 'fde06c08-43a0-43a0-8201-1588c39f452a', '7ce5f15c-7a05-40fd-a429-11daed020d24', 'subtopic'::public.curated_course_node_type, 'Cultivation', 'Cultivation identifies a specific object, distinction, or relationship within microbial world and methods. Learners need to recognize and use it before combining this module''s ideas in later work. After microscopy, cultivation supplies what is needed to address aseptic technique.', 1),
  ('62373acd-f2ea-4346-a7e4-c2b308523725', 'fde06c08-43a0-43a0-8201-1588c39f452a', '7ce5f15c-7a05-40fd-a429-11daed020d24', 'subtopic'::public.curated_course_node_type, 'Aseptic technique', 'Aseptic technique identifies a specific object, distinction, or relationship within microbial world and methods. Learners need to recognize and use it before combining this module''s ideas in later work. After cultivation, aseptic technique supplies what is needed to address biosafety.', 2),
  ('390668a0-cb8a-4ed9-8f40-4c51018692e2', 'fde06c08-43a0-43a0-8201-1588c39f452a', '7ce5f15c-7a05-40fd-a429-11daed020d24', 'subtopic'::public.curated_course_node_type, 'Biosafety', 'Biosafety explains how microbial world and methods behaves under misuse, faults, or constraints, which is essential for responsible real-world application. After aseptic technique, biosafety supplies what is needed to address evidence limits.', 3),
  ('1791be81-8ca0-4179-94c4-2ef1ab163857', 'fde06c08-43a0-43a0-8201-1588c39f452a', '7ce5f15c-7a05-40fd-a429-11daed020d24', 'subtopic'::public.curated_course_node_type, 'Evidence limits', 'Evidence limits makes difficult behavior in microbial world and methods tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, evidence limits carries the completed idea into cell structure.', 4),
  ('f29e1d05-83be-472e-89d9-bd86663fc6de', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Cell structure', 'This module builds directly on microbial world and methods and develops cell structure. It belongs here because its methods and distinctions are prerequisites for growth.', 1),
  ('3a5929a7-1082-4417-9319-ce5f2edb4526', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f29e1d05-83be-472e-89d9-bd86663fc6de', 'subtopic'::public.curated_course_node_type, 'Bacteria', 'Bacteria identifies a specific object, distinction, or relationship within cell structure. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before archaea because that next topic assumes this starting point.', 0),
  ('8ec4b4b9-f06d-4b73-88a8-6ec304c087f0', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f29e1d05-83be-472e-89d9-bd86663fc6de', 'subtopic'::public.curated_course_node_type, 'Archaea', 'Archaea identifies a specific object, distinction, or relationship within cell structure. Learners need to recognize and use it before combining this module''s ideas in later work. After bacteria, archaea supplies what is needed to address microbial eukaryotes.', 1),
  ('202fbdbb-29a2-4b18-b9d4-2674e49ceb5c', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f29e1d05-83be-472e-89d9-bd86663fc6de', 'subtopic'::public.curated_course_node_type, 'Microbial eukaryotes', 'Microbial eukaryotes identifies a specific object, distinction, or relationship within cell structure. Learners need to recognize and use it before combining this module''s ideas in later work. After archaea, microbial eukaryotes supplies what is needed to address envelopes.', 2),
  ('4244e673-69af-4539-b2b2-96b5c4df8bb0', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f29e1d05-83be-472e-89d9-bd86663fc6de', 'subtopic'::public.curated_course_node_type, 'Envelopes', 'Envelopes identifies a specific object, distinction, or relationship within cell structure. Learners need to recognize and use it before combining this module''s ideas in later work. After microbial eukaryotes, envelopes supplies what is needed to address motility.', 3),
  ('fc2a7bf6-4030-49f1-9eb2-9e8f34195ad9', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f29e1d05-83be-472e-89d9-bd86663fc6de', 'subtopic'::public.curated_course_node_type, 'Motility', 'Motility identifies a specific object, distinction, or relationship within cell structure. Learners need to recognize and use it before combining this module''s ideas in later work. After envelopes, motility supplies what is needed to address spores.', 4),
  ('b6077ef5-6871-4292-ba22-da1ac3ef8d92', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f29e1d05-83be-472e-89d9-bd86663fc6de', 'subtopic'::public.curated_course_node_type, 'Spores', 'Spores identifies a specific object, distinction, or relationship within cell structure. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, spores carries the completed idea into growth.', 5),
  ('75004520-5222-4864-9a42-b9a50cd1f021', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Growth', 'This module builds directly on cell structure and develops growth. It belongs here because its methods and distinctions are prerequisites for metabolism i.', 2),
  ('a98ab334-14bd-4e6a-a043-175d527b087c', 'fde06c08-43a0-43a0-8201-1588c39f452a', '75004520-5222-4864-9a42-b9a50cd1f021', 'subtopic'::public.curated_course_node_type, 'Division', 'Division identifies a specific object, distinction, or relationship within growth. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before growth curves because that next topic assumes this starting point.', 0),
  ('cd50ca8f-7ade-4780-bcbf-a486b5759eea', 'fde06c08-43a0-43a0-8201-1588c39f452a', '75004520-5222-4864-9a42-b9a50cd1f021', 'subtopic'::public.curated_course_node_type, 'Growth curves', 'Growth curves identifies a specific object, distinction, or relationship within growth. Learners need to recognize and use it before combining this module''s ideas in later work. After division, growth curves supplies what is needed to address environmental limits.', 1),
  ('3d2aca20-b295-4f80-a589-1437cd516631', 'fde06c08-43a0-43a0-8201-1588c39f452a', '75004520-5222-4864-9a42-b9a50cd1f021', 'subtopic'::public.curated_course_node_type, 'Environmental limits', 'Environmental limits makes difficult behavior in growth tractable while exposing the assumptions and accuracy limits used by later methods. After growth curves, environmental limits supplies what is needed to address measurement.', 2),
  ('504c12fb-7da6-4eab-b8d0-412036494d33', 'fde06c08-43a0-43a0-8201-1588c39f452a', '75004520-5222-4864-9a42-b9a50cd1f021', 'subtopic'::public.curated_course_node_type, 'Measurement', 'Measurement connects growth to observable evidence and defines what a valid measurement or interpretation must support. After environmental limits, measurement supplies what is needed to address control.', 3),
  ('61dd7abc-2f1e-42c4-8654-e8e008399760', 'fde06c08-43a0-43a0-8201-1588c39f452a', '75004520-5222-4864-9a42-b9a50cd1f021', 'subtopic'::public.curated_course_node_type, 'Control', 'Control explains how growth behaves under misuse, faults, or constraints, which is essential for responsible real-world application. As the final topic in this module, control carries the completed idea into metabolism i.', 4),
  ('186283ea-57eb-4472-ae31-4ece1cbfcbc9', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Metabolism I', 'This module builds directly on growth and develops metabolism i. It belongs here because its methods and distinctions are prerequisites for metabolism ii.', 3),
  ('9fd3840f-5257-4c44-988e-122b97e32d93', 'fde06c08-43a0-43a0-8201-1588c39f452a', '186283ea-57eb-4472-ae31-4ece1cbfcbc9', 'subtopic'::public.curated_course_node_type, 'Energy conservation', 'Energy conservation is a governing quantity in metabolism i, linking local calculations to system-level behavior and offering a consistency check. It appears before respiration because that next topic assumes this starting point.', 0),
  ('894987d5-e5c0-48e3-aa4f-5bf6350280d1', 'fde06c08-43a0-43a0-8201-1588c39f452a', '186283ea-57eb-4472-ae31-4ece1cbfcbc9', 'subtopic'::public.curated_course_node_type, 'Respiration', 'Respiration identifies a specific object, distinction, or relationship within metabolism i. Learners need to recognize and use it before combining this module''s ideas in later work. After energy conservation, respiration supplies what is needed to address fermentation.', 1),
  ('6e1884b5-e2a2-4616-abbb-24d2146ddedb', 'fde06c08-43a0-43a0-8201-1588c39f452a', '186283ea-57eb-4472-ae31-4ece1cbfcbc9', 'subtopic'::public.curated_course_node_type, 'Fermentation', 'Fermentation identifies a specific object, distinction, or relationship within metabolism i. Learners need to recognize and use it before combining this module''s ideas in later work. After respiration, fermentation supplies what is needed to address redox.', 2),
  ('648f2e4d-b1aa-44df-8d21-8739bfcd32b6', 'fde06c08-43a0-43a0-8201-1588c39f452a', '186283ea-57eb-4472-ae31-4ece1cbfcbc9', 'subtopic'::public.curated_course_node_type, 'Redox', 'Redox identifies a specific object, distinction, or relationship within metabolism i. Learners need to recognize and use it before combining this module''s ideas in later work. After fermentation, redox supplies what is needed to address bioenergetics.', 3),
  ('cb49402c-d0ef-47c4-861e-dc43a0945b63', 'fde06c08-43a0-43a0-8201-1588c39f452a', '186283ea-57eb-4472-ae31-4ece1cbfcbc9', 'subtopic'::public.curated_course_node_type, 'Bioenergetics', 'Bioenergetics identifies a specific object, distinction, or relationship within metabolism i. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, bioenergetics carries the completed idea into metabolism ii.', 4),
  ('44d10d9d-bf90-4138-b4e9-a7f23d03ccb2', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Metabolism II', 'This module builds directly on metabolism i and develops metabolism ii. It belongs here because its methods and distinctions are prerequisites for microbial genetics.', 4),
  ('7e8170d7-7976-40ab-9df0-2789a3229355', 'fde06c08-43a0-43a0-8201-1588c39f452a', '44d10d9d-bf90-4138-b4e9-a7f23d03ccb2', 'subtopic'::public.curated_course_node_type, 'Phototrophy', 'Phototrophy identifies a specific object, distinction, or relationship within metabolism ii. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before lithotrophy because that next topic assumes this starting point.', 0),
  ('78f7eb6a-09ee-4f71-a9c7-6e4cd6154dde', 'fde06c08-43a0-43a0-8201-1588c39f452a', '44d10d9d-bf90-4138-b4e9-a7f23d03ccb2', 'subtopic'::public.curated_course_node_type, 'Lithotrophy', 'Lithotrophy identifies a specific object, distinction, or relationship within metabolism ii. Learners need to recognize and use it before combining this module''s ideas in later work. After phototrophy, lithotrophy supplies what is needed to address carbon/nitrogen assimilation.', 1),
  ('5b0cfed8-8916-4cda-a4ce-ab0f85c3075b', 'fde06c08-43a0-43a0-8201-1588c39f452a', '44d10d9d-bf90-4138-b4e9-a7f23d03ccb2', 'subtopic'::public.curated_course_node_type, 'Carbon/nitrogen assimilation', 'Carbon/nitrogen assimilation identifies a specific object, distinction, or relationship within metabolism ii. Learners need to recognize and use it before combining this module''s ideas in later work. After lithotrophy, carbon/nitrogen assimilation supplies what is needed to address metabolic diversity.', 2),
  ('e215a332-86c4-4813-ae32-9446a78ebdf7', 'fde06c08-43a0-43a0-8201-1588c39f452a', '44d10d9d-bf90-4138-b4e9-a7f23d03ccb2', 'subtopic'::public.curated_course_node_type, 'Metabolic diversity', 'Metabolic diversity identifies a specific object, distinction, or relationship within metabolism ii. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, metabolic diversity carries the completed idea into microbial genetics.', 3),
  ('fe3d078b-cdea-4cd0-a7df-22fc53bcc54a', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Microbial genetics', 'This module builds directly on metabolism ii and develops microbial genetics. It belongs here because its methods and distinctions are prerequisites for horizontal gene transfer and evolution.', 5),
  ('abba0a28-1925-4379-89c7-8a8b1fbb2214', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'fe3d078b-cdea-4cd0-a7df-22fc53bcc54a', 'subtopic'::public.curated_course_node_type, 'Replication', 'Replication identifies a specific object, distinction, or relationship within microbial genetics. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before mutation because that next topic assumes this starting point.', 0),
  ('b803c08c-14c6-4055-85d3-b7388adfa251', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'fe3d078b-cdea-4cd0-a7df-22fc53bcc54a', 'subtopic'::public.curated_course_node_type, 'Mutation', 'Mutation identifies a specific object, distinction, or relationship within microbial genetics. Learners need to recognize and use it before combining this module''s ideas in later work. After replication, mutation supplies what is needed to address gene regulation.', 1),
  ('df252f78-ab93-427c-879d-09643f1d5b67', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'fe3d078b-cdea-4cd0-a7df-22fc53bcc54a', 'subtopic'::public.curated_course_node_type, 'Gene regulation', 'Gene regulation identifies a specific object, distinction, or relationship within microbial genetics. Learners need to recognize and use it before combining this module''s ideas in later work. After mutation, gene regulation supplies what is needed to address operons.', 2),
  ('1b5cd2a8-6ad8-45f2-9a6b-666325210e66', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'fe3d078b-cdea-4cd0-a7df-22fc53bcc54a', 'subtopic'::public.curated_course_node_type, 'Operons', 'Operons identifies a specific object, distinction, or relationship within microbial genetics. Learners need to recognize and use it before combining this module''s ideas in later work. After gene regulation, operons supplies what is needed to address mobile elements.', 3),
  ('08e948ee-ddeb-46b6-ac8c-0bf5e0e9c538', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'fe3d078b-cdea-4cd0-a7df-22fc53bcc54a', 'subtopic'::public.curated_course_node_type, 'Mobile elements', 'Mobile elements identifies a specific object, distinction, or relationship within microbial genetics. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, mobile elements carries the completed idea into horizontal gene transfer and evolution.', 4),
  ('de705bc1-9978-456a-af84-8a29faac39be', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Horizontal gene transfer and evolution', 'This module builds directly on microbial genetics and develops horizontal gene transfer and evolution. It belongs here because its methods and distinctions are prerequisites for viruses and phages.', 6),
  ('d355ef44-774b-43f2-a94d-245384b293d2', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'de705bc1-9978-456a-af84-8a29faac39be', 'subtopic'::public.curated_course_node_type, 'Transformation', 'Transformation makes difficult behavior in horizontal gene transfer and evolution tractable while exposing the assumptions and accuracy limits used by later methods. It appears before transduction because that next topic assumes this starting point.', 0),
  ('e20ea5e2-1e5c-4fda-b287-e7f6bc111ef7', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'de705bc1-9978-456a-af84-8a29faac39be', 'subtopic'::public.curated_course_node_type, 'Transduction', 'Transduction identifies a specific object, distinction, or relationship within horizontal gene transfer and evolution. Learners need to recognize and use it before combining this module''s ideas in later work. After transformation, transduction supplies what is needed to address conjugation.', 1),
  ('2b6352ed-5a7e-4448-9bde-b96e8a9e61fa', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'de705bc1-9978-456a-af84-8a29faac39be', 'subtopic'::public.curated_course_node_type, 'Conjugation', 'Conjugation identifies a specific object, distinction, or relationship within horizontal gene transfer and evolution. Learners need to recognize and use it before combining this module''s ideas in later work. After transduction, conjugation supplies what is needed to address resistance.', 2);
