  ('a35e067f-a6ca-4a96-9ac9-979eec2cb982', 'fde06c08-43a0-43a0-8201-1588c39f452a', '6ae9aa35-de69-408b-b5b5-9c711ad5728e', 'subtopic'::public.curated_course_node_type, 'Microbiomes', 'Microbiomes identifies a specific object, distinction, or relationship within microbial ecology. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, microbiomes carries the completed idea into host–microbe interactions.', 4),
  ('c61224cd-c66c-421f-857e-0be60a72db04', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Host–microbe interactions', 'This module builds directly on microbial ecology and develops host–microbe interactions. It belongs here because its methods and distinctions are prerequisites for antimicrobials and epidemiology.', 9),
  ('f0b4a287-7239-4a99-835b-74aedf8dd958', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'c61224cd-c66c-421f-857e-0be60a72db04', 'subtopic'::public.curated_course_node_type, 'Colonization', 'Colonization identifies a specific object, distinction, or relationship within host–microbe interactions. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before virulence because that next topic assumes this starting point.', 0),
  ('46588f17-388e-487c-a70a-65978b85a6bd', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'c61224cd-c66c-421f-857e-0be60a72db04', 'subtopic'::public.curated_course_node_type, 'Virulence', 'Virulence identifies a specific object, distinction, or relationship within host–microbe interactions. Learners need to recognize and use it before combining this module''s ideas in later work. After colonization, virulence supplies what is needed to address innate/adaptive defenses.', 1),
  ('74204fa8-c51f-4845-a921-a0979ca700ef', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'c61224cd-c66c-421f-857e-0be60a72db04', 'subtopic'::public.curated_course_node_type, 'Innate/adaptive defenses', 'Innate/adaptive defenses identifies a specific object, distinction, or relationship within host–microbe interactions. Learners need to recognize and use it before combining this module''s ideas in later work. After virulence, innate/adaptive defenses supplies what is needed to address dysbiosis.', 2),
  ('a47a9981-d2c6-49aa-bb82-dc50dbaa0283', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'c61224cd-c66c-421f-857e-0be60a72db04', 'subtopic'::public.curated_course_node_type, 'Dysbiosis', 'Dysbiosis identifies a specific object, distinction, or relationship within host–microbe interactions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, dysbiosis carries the completed idea into antimicrobials and epidemiology.', 3),
  ('f4e502b4-3788-4024-96d3-c3a029a9cd28', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Antimicrobials and epidemiology', 'This module builds directly on host–microbe interactions and develops antimicrobials and epidemiology. It belongs here because its methods and distinctions are prerequisites for applied and systems microbiology.', 10),
  ('f325f689-7a7f-4594-ac8e-f584ef1e449e', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f4e502b4-3788-4024-96d3-c3a029a9cd28', 'subtopic'::public.curated_course_node_type, 'Targets', 'Targets identifies a specific object, distinction, or relationship within antimicrobials and epidemiology. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before resistance because that next topic assumes this starting point.', 0),
  ('4a69951f-6cbf-44dc-91dd-77f760489c81', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f4e502b4-3788-4024-96d3-c3a029a9cd28', 'subtopic'::public.curated_course_node_type, 'Resistance', 'Resistance identifies a specific object, distinction, or relationship within antimicrobials and epidemiology. Learners need to recognize and use it before combining this module''s ideas in later work. After targets, resistance supplies what is needed to address susceptibility.', 1),
  ('bb40207c-7c22-418a-9c47-8f005bed67b8', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f4e502b4-3788-4024-96d3-c3a029a9cd28', 'subtopic'::public.curated_course_node_type, 'Susceptibility', 'Susceptibility identifies a specific object, distinction, or relationship within antimicrobials and epidemiology. Learners need to recognize and use it before combining this module''s ideas in later work. After resistance, susceptibility supplies what is needed to address transmission.', 2),
  ('0872d05b-5d92-478a-b297-32d5f62fc8e4', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f4e502b4-3788-4024-96d3-c3a029a9cd28', 'subtopic'::public.curated_course_node_type, 'Transmission', 'Transmission identifies a specific object, distinction, or relationship within antimicrobials and epidemiology. Learners need to recognize and use it before combining this module''s ideas in later work. After susceptibility, transmission supplies what is needed to address stewardship.', 3),
  ('3fc6f038-4ed9-432d-a9c2-78d956bebdee', 'fde06c08-43a0-43a0-8201-1588c39f452a', 'f4e502b4-3788-4024-96d3-c3a029a9cd28', 'subtopic'::public.curated_course_node_type, 'Stewardship', 'Stewardship explains how antimicrobials and epidemiology behaves under misuse, faults, or constraints, which is essential for responsible real-world application. As the final topic in this module, stewardship carries the completed idea into applied and systems microbiology.', 4),
  ('8102db5a-1519-455a-9984-3b13910d2e4d', 'fde06c08-43a0-43a0-8201-1588c39f452a', null, 'topic'::public.curated_course_node_type, 'Applied and systems microbiology', 'This culminating module draws on antimicrobials and epidemiology and develops applied and systems microbiology. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('3373f197-7a2e-4b21-99bd-849468962cae', 'fde06c08-43a0-43a0-8201-1588c39f452a', '8102db5a-1519-455a-9984-3b13910d2e4d', 'subtopic'::public.curated_course_node_type, 'Diagnostics', 'Diagnostics makes the validity limits of applied and systems microbiology explicit, showing when an otherwise correct method or system can become unreliable. It appears before fermentation because that next topic assumes this starting point.', 0),
  ('c0d69f18-12ef-4e16-ac09-8df6e10d73b5', 'fde06c08-43a0-43a0-8201-1588c39f452a', '8102db5a-1519-455a-9984-3b13910d2e4d', 'subtopic'::public.curated_course_node_type, 'Fermentation', 'Fermentation identifies a specific object, distinction, or relationship within applied and systems microbiology. Learners need to recognize and use it before combining this module''s ideas in later work. After diagnostics, fermentation supplies what is needed to address synthetic biology.', 1),
  ('6f37c184-2bb6-4630-844f-e88eb4374751', 'fde06c08-43a0-43a0-8201-1588c39f452a', '8102db5a-1519-455a-9984-3b13910d2e4d', 'subtopic'::public.curated_course_node_type, 'Synthetic biology', 'Synthetic biology identifies a specific object, distinction, or relationship within applied and systems microbiology. Learners need to recognize and use it before combining this module''s ideas in later work. After fermentation, synthetic biology supplies what is needed to address omics.', 2),
  ('b2f52655-c691-4eee-bcfd-a8e69d7089eb', 'fde06c08-43a0-43a0-8201-1588c39f452a', '8102db5a-1519-455a-9984-3b13910d2e4d', 'subtopic'::public.curated_course_node_type, 'Omics', 'Omics identifies a specific object, distinction, or relationship within applied and systems microbiology. Learners need to recognize and use it before combining this module''s ideas in later work. After synthetic biology, omics supplies what is needed to address ethics.', 3),
  ('fd0ed802-30f5-4776-9564-41cde39f7a23', 'fde06c08-43a0-43a0-8201-1588c39f452a', '8102db5a-1519-455a-9984-3b13910d2e4d', 'subtopic'::public.curated_course_node_type, 'Ethics', 'Ethics identifies a specific object, distinction, or relationship within applied and systems microbiology. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, ethics requires ideas from the complete path to be integrated and transferred.', 4);
